def get_distances(coords: List[float]) -> List[float]:
    """ Given a list of coordinates, return a list with the distances between each pair of points """
    distances = []
    for i in range(len(coords)):
        for j in range(i + 1, len(coords)):
            distances.append(
                abs(coords[i] - coords[j])
            )

    return distances


