def factorize(n: int):
    """
    Factorize n into a product of primes.
    >>> factorize(12)
    [2, 2, 3]
    """
    factorized = []
    for i in range(2, n + 1):
        if n % i == 0:
            factorized.append(i)
    return factorized


def root_finder(f, a, b, eps=1e-12):
    """
    >>> root_finder(lambda x: x ** 3 - 2, 1, 3)
    1.3333333333333333
    """
    x = (a + b) / 2
    while abs(b - a) > eps:
        if f(x) * f(a) > 0:
            a = x
        else:
            b = x
        x = (a + b) / 2
    return x


def f(x):
    return x ** 3 - 2


def root_finder2(f, a, b, eps=1e-12):
    """
    >>> root_finder2(lambda x: x ** 3 - 2, 1, 3)
    1.3333333333333333
    """
    x = (a + b) / 2
    while abs(b - a) > eps:
        if f(a) * f(x) > 0:
            a = x
        else:
            b = x
        x = (a + b) / 2
    return x


