def encode_morse(s: str):
    """
    takes as input string. Returns encoded string in morse code format.
    """
    return " ".join([MORSE[ch.upper()] for ch in s])


def decode_morse(s: str):
    """
    takes as input string. Returns decoded string in morse code format.
    """
    return "".join([MORSE_INV[ch.strip()] for ch in s.split(" ")])


print(decode_morse(encode_morse("abcdefgh")))


def encode_base64(s: str):
    """
    takes as input string. Returns encoded string in base64 format.
    """
    return " ".join([format(ord(ch), 'b').zfill(7) for ch in s])


def decode_base64(s: str):
    """
    takes as input string. Returns decoded string in base64 format.
    """
    return "".join([chr(int(ch, 2)) for ch in s.split(" ")])


print(decode_base64(encode_base64("abcdefgh")))


def encode_hexdump(s: str):
    """
    takes as input string. Returns encoded string in hexdump format.
    """
    return " ".join([format(ord(ch), 'x') for ch in s])


def decode_hexdump(s: str):
    """
    takes as input string. Returns decoded string in hexdump format.
    """
    return "".join([chr(int(ch, 16)) for ch in s.split(" ")])


print(decode_hexdump(encode_hexdump("abcdefgh")))


def encode_url(s: str):
    """
    takes as input string. Returns encoded string in url format.
    """
    return "".join([f"%{format(ord(ch), 'x').zfill(2)}" for ch in s])


def decode_url(s: str):
    """
    takes as input string. Returns decoded string in url format.
    """
    return "".join([chr(int(ch, 16)) for ch in [s[i:i + 2] for i in range(0, len(s), 2)]])


print(decode_url(encode_url("abcdefgh")))

