def triangle_area(a, b, c):
    '''
    Given the lengths of the three sides of a triangle. Return the area of
    the triangle rounded to 2 decimal points if the three sides form a valid triangle. 
    Otherwise return -1
    Three sides make a valid triangle when the sum of any two sides is greater 
    than the third side.
    Example:
    triangle_area(3, 4, 5) == 6.00
    triangle_area(1, 2, 10) == -1
    '''

    #write your code here
    def sortList (list1):#sorting function for later on
        list1=sorted(list1);

        while len(list1)>len(set(list1)):
            for i in range(len(list1)-1):
                if list1[i]==list1[i+1]:
                    del list1[i];
        return list1;


    lis=[a,b,c]; #creating a list with all length values that will be sorted and checked for invalidity afterward
    result=-1; #default value as negative one since it won't meet condition
    lisSorted = sortList(lis); #calling sorting funtion with this list first

    try:#try/except block to catch non-numeric input cases before they are even passed into functions
        a,b,c=(float(lisSorted[0]), float(lisSorted[1]) , float(lisSorted[2]))
    except ValueError :#if user inputs letters or characters instead of numbers
        print("Please only use numbers");
       ##return(-1);#to end program early 

    if ((a<0)|(b <0 )|(c <0)):#checks if there is an entry less than zero which would also cause errors to occur downstream
        pass ;
    else :
        sumOne=((abs(a)+ abs(b)));
        sumTwo=abs(sumOne-abs(c));
        if sumOne>sumTwo:
           result=round(.5*(a*b),2);#this formula finds area using Heron's Formula but is specific for triangles where the largest angle is at most pi radians or 90 degrees
        elif sumTwo>=sumOne:
               result="Invalid Input";

    return(result);     

