def is_prime(n):
    if n <= 1:
        return False
    for i in range(2, n):
        if n % i == 0:
            return False
    return True

def intersection(interval1, interval2):
    if interval1[0] <= interval2[0] <= interval1[1] and interval1[0] <= interval2[1] <= interval1[1]:
        return "YES" if is_prime(interval2[0]-interval2[1]+1) else "NO"
    else:
        return "NO"




