def get_string_from_file(filepath):
    """
    Given the path of a file, read its contents and return the contents as a string.
    If the file doesn't exist, return None.

    >>> get_string_from_file('file.txt')
    """

    import os

    if not os.path.exists(filepath):
        return None

    with open(filepath) as f:
        return f.read()


def get_hash_from_file(filepath):
    """
    Given the path of a file, return its md5 hash equivalent string.
    If the file doesn't exist, return None.

    >>> get_hash_from_file('file.txt')
    """

    return string_to_md5(get_string_from_file(filepath))


